/**
 * `/llms.txt` for the static build (llms.txt convention), generated by
 * `publish-static.ts` from the built pages rather than from search hints.
 *
 * It lists exactly the pages the sitemap lists (`sitemapEntry`), each with its
 * own title and meta description: the page copy that carries the page's status
 * wording. A page's publication date and its "Historical" marker
 * (`data-historical-page`, set by the blog post route) stay on the line, so a
 * dated or superseded post never reads as current. An earlier version built the
 * file from the search catalog's short hints, which dropped that context.
 */
import { sitemapEntry } from "./sitemap.ts";

export type LlmsPage = {
  loc: string;
  title: string;
  description: string;
  published?: string;
  historical: boolean;
};

const NAMED: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" };

function decode(value: string): string {
  return value.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, entity: string) => {
    const key = entity.toLowerCase();
    if (key.startsWith("#x")) return String.fromCodePoint(parseInt(key.slice(2), 16));
    if (key.startsWith("#")) return String.fromCodePoint(Number(key.slice(1)));
    return NAMED[key] ?? match;
  });
}

export function llmsPage(html: string): LlmsPage | null {
  const entry = sitemapEntry(html);
  if (!entry) return null;
  const title = /<title>([^<]*)<\/title>/.exec(html)?.[1];
  const description = /<meta name="description" content="([^"]*)"/.exec(html)?.[1];
  if (!title || !description) return null;
  const published = /"datePublished":"(\d{4}-\d{2}-\d{2})/.exec(html)?.[1];
  return {
    loc: entry.loc,
    title: decode(title).replace(/ · Quesar$/, ""),
    description: decode(description),
    ...(published ? { published } : {}),
    historical: html.includes("data-historical-page"),
  };
}

/** Sections in reading order; any other first path segment follows, title-cased. */
const SECTIONS = ["products", "docs", "research", "blog", "projects", "team", "source", "showcase"];

function segments(loc: string): string[] {
  return new URL(loc).pathname.split("/").filter(Boolean);
}

function sectionOf(loc: string, sections: ReadonlySet<string>): string {
  const [first] = segments(loc);
  return first && sections.has(first) ? first : "site";
}

const label = (key: string) =>
  key === "site" ? "Site" : key.charAt(0).toUpperCase() + key.slice(1).replace(/-/g, " ");

function line(page: LlmsPage): string {
  const notes = [
    page.published ? `published ${page.published}` : null,
    page.historical ? "historical" : null,
  ].filter(Boolean);
  return `- [${page.title}](${page.loc}): ${page.description}${notes.length ? ` (${notes.join("; ")})` : ""}`;
}

export function buildLlmsTxt(pages: readonly LlmsPage[], siteName: string): string {
  // A first segment is a section when some page lives below it (e.g. /blog/x).
  const sections = new Set(
    pages
      .map((page) => segments(page.loc))
      .flatMap((parts) => (parts.length > 1 ? [parts[0]] : [])),
  );
  const groups = new Map<string, LlmsPage[]>();
  for (const page of pages) {
    const key = sectionOf(page.loc, sections);
    groups.set(key, [...(groups.get(key) ?? []), page]);
  }
  const depth = (page: LlmsPage) => segments(page.loc).length;
  const order = [
    "site",
    ...SECTIONS,
    ...[...groups.keys()].filter((k) => k !== "site" && !SECTIONS.includes(k)).sort(),
  ];
  const home = pages.find((page) => segments(page.loc).length === 0);
  const blocks = order.flatMap((key) => {
    const list = groups.get(key);
    if (!list?.length) return [];
    const sorted = [...list].sort((a, b) => depth(a) - depth(b) || a.loc.localeCompare(b.loc));
    return [`## ${label(key)}\n${sorted.map(line).join("\n")}`];
  });
  const intro = home ? `> ${home.description}\n\n` : "";
  return `# ${siteName}\n\n${intro}${blocks.join("\n\n")}\n`;
}
